UPDATE businesses SET description = 'Garden Mecca is a plant nursery and garden centre serving both Pretoria and Johannesburg from its premises at the corner of Vindhella and Godiva Road in Valhalla. The business stocks a wide range of plants and garden supplies, including soil and gardening accessories, and produces some of its own garden décor items in-house rather than relying solely on bought-in stock. Beyond walk-in retail, Garden Mecca also handles outbound orders dispatched by truck, consolidating deliveries into full loads to keep transport costs down, with a standard turnaround of five to ten business days once an order is placed online or in-store. This combination of an in-person garden centre and an organised delivery operation allows it to serve home gardeners and landscaping customers across a wide area spanning two provinces, rather than only those able to visit its Valhalla location in person. Customers who do visit are able to browse a broad selection of plant varieties alongside the nursery''s other stock in a garden centre setting.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.gardenmecca.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'garden-mecca-valhalla' AND description = 'Garden Mecca is a nursery and garden centre in Valhalla, also offering landscaping contracting services, serving home gardeners and landscaping clients across Pretoria and Johannesburg.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
