UPDATE businesses SET description = 'Green Reflections Nursery is a specialist wholesale plant nursery on Plot 1 along the R104 in Donkerhoek, focused on Azaleas, Clematis and Camellias. The nursery''s horticulturists hand-select plants for their beauty and health, aiming to supply varieties that are straightforward for home gardeners to care for once established. Its azaleas, more correctly rhododendrons, are evergreen shrubs valued for their foliage and for the single or double blooms they produce in colours including pink, red, white, purple and orange, appearing in late winter, spring and autumn; plants range from small, low-growing varieties to larger shrubs reaching around two metres. The nursery advises that these shrubs do best in acidic soil with cool roots, undisturbed root systems and deep mulching, and that potted azaleas need good-quality soil and regular fertilising to flourish. Its clematis stock consists of deciduous flowering creepers that produce blooms from late spring through to late autumn. The public can visit the nursery in person during opening hours, though it does not open on weekends or public holidays.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.greenreflections.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'green-reflections-nursery-donkerhoek' AND description = 'Green Reflections Nursery is a wholesale plant nursery in Donkerhoek specialising in Azaleas, Clematis and Camellias, with horticulturists bringing over 30 years of growing experience.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
