UPDATE businesses SET description = 'Health on Tap is a water-refill store at Hazeldean Square that has been producing drinking water since 2019. Water sold in the shop is bottled on site after passing through a nine-step process that includes sediment filtration, UV sterilisation, carbon filtering, reverse osmosis, deionisation, mineralisation, pH enrichment, ozone treatment and a final vortex stage, aimed at consistent taste and quality. From this base process the shop produces two main types of drinking water: a mineralised water with a pH of around 7.5 and roughly 50 parts per million of added minerals, and an alkaline water with a higher pH of around 9.5 and about 100 parts per million of minerals. Besides its water range, Health on Tap also stocks a selection of other health products, including raw honey sourced from a farm, sugar-free water supplements, coffee, and supplements such as Moringa and Lion''s Mane. Customers are served in person at the Hazeldean Square store, where staff can talk through the different water options and other products on the shelves.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.healthontap.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'health-on-tap-hazeldean' AND description = 'A water-refill shop at Hazeldean Square using reverse-osmosis filtration with zero total dissolved solids to produce mineralised and alkaline drinking water, alongside supplementary health products.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
